dict(tf=[('实现','理想还没有实现。','The aspiration has not yet been achieved.','The goal is achieved.',False,'还没有 explicitly denies completion.'),('同时','两个人同时说，我没听清。','Two people spoke at once and I did not hear clearly.','The overlapping speech was unclear.',True,'没听清 describes the result.')],reply=[('才','上周三遍，这周两遍就懂了。','Three readings last week; two this week were enough.',['越来越清楚了。','所以你永远不用读。','你就是全国明星。'],0,'Describe the supported change.'),('广告','广告说一定完美，记录没有。','The advertisement promises perfection; the record does not.',['先看记录，不要只看广告。','广告就是所有事实。','记录一定是颜色。'],0,'Use actual evidence.')],fill=[('今后','今后每周记录一次。','Record once a week from now on.'),('小说','这本小说还没有看完。','This novel has not yet been finished.')],match=[('画',[('她想成为画家。','She aspires to become a painter.'),('这张画儿是她画的。','She made this drawing.'),('这位作家写小说。','This writer writes fiction.')]),('越来越',[('越来越清楚。','Becoming clearer over time.'),('两个人同时说。','Two people speak at once.'),('早就想参加。','Has wanted to join for a long time.')])]),
