write(u,'每个人的故事不一样',['Give age, date and other short nominal predicates','Keep a personal background separate from an unsupported generalization','Read source senses of 得、长 and 省 in context'],[
('变','to change','thay đổi','verb','计划变了，先问清楚。','The plan changed; clarify it first.'),('变成','to turn into; become','trở thành','verb','小组变成了五个人。','The group has become a group of five.'),('得','to obtain; gain','đạt được','verb','她得了三分，不是满分。','She scored three points, not full marks.'),('得出','to arrive at a conclusion','rút ra','verb','先看事实，再得出结论。','Look at facts before drawing a conclusion.'),('到处','everywhere','khắp nơi','adverb','到处都有消息，不是到处都一样。','There is information everywhere, but it is not identical everywhere.'),('分开','to separate; apart','tách ra','verb','先把两个人的记录分开。','First separate the two people’s records.'),('结果','result; outcome','kết quả','noun','结果出来了，再讨论。','Discuss once the results are available.'),('选','to select','chọn','verb','你选一段，我选另一段。','You choose one passage and I choose another.'),('想到','to think of; realize','nghĩ đến','verb','我想到一个问题，先问。','A question occurred to me; I will ask first.'),('想起','to recall','nhớ lại','verb','我想起过去的朋友。','I remember a friend from the past.'),('省','province','tỉnh','noun','她来自这个省，不是这个城市。','She comes from this province, not this city.'),('许多','many; much','nhiều','adjective','许多人有不同的故事。','Many people have different stories.'),('以上','above; at least','trên; trở lên','noun','三分以上包括三分。','At least three points includes three.'),('以下','below; at most','dưới; trở xuống','noun','三分以下包括三分。','At most three points includes three.'),('以外','outside; except','ngoài; ngoại trừ','noun','今天以外，时间还没定。','Other than today, the times are not settled.'),('长','to grow','lớn lên; mọc','verb','她在这个城市长大。','She grew up in this city.'),('中心','centre','trung tâm','noun','中心在前面，先看地图。','The centre is ahead; check the map first.'),('市','city; municipality','thành phố','noun','这个市有几个区。','This city has several districts.'),('市长','mayor','thị trưởng','noun','市长是职务，不是每个人的姓。','Mayor is an office, not everyone’s surname.'),('商人','merchant; businessperson','thương nhân','noun','她是商人，弟弟还是学生。','She is a businessperson; her younger brother is still a student.'),('信用卡','credit card','thẻ tín dụng','noun','这里不能用信用卡，先问别的方式。','Credit cards cannot be used here; ask about another method.'),('过去','the past; formerly','quá khứ; trước kia','noun','过去住这里，现在住别处。','Used to live here; now lives elsewhere.')],
[grammar(u,'二48','名词性谓语：年龄、日期等','Recognize bounded short nominal statements',
'我二十二岁 and 今天星期三 can stand without 是 in familiar age/date contexts. This is not a rule to delete 是 from every identification: 她是商人 remains a normal noun classification. Negative age/date claims normally use 不是: 今天不是星期二. Ask what is being stated before expanding an omitted verb.',[('我二十二岁。','I am twenty-two.'),('今天星期三。','Today is Wednesday.'),('她是商人。','She is a businessperson.')],('她商人。这里是在介绍身份。','她是商人。','Keep 是 in this neutral identity introduction; short age/date patterns do not license every noun predicate.')),
grammar(u,'二54','主谓句：名词性谓语句','Interpret topic, nominal predicate and scope',
'今天星期三 has the topic 今天 and nominal predicate 星期三. 她今年二十二岁 states her age this year, not her birthday or birthplace. 这本书三十五块 gives a price in context. Use 不是 to reject a stated value and supply the actual one; these patterns do not establish unrelated facts.',[('她今年二十二岁。','She is twenty-two this year.'),('这本书三十五块。','This book is thirty-five yuan.'),('今天不是星期二，是星期三。','Today is not Tuesday; it is Wednesday.')],('她今年二十二岁，所以知道生日是哪天。','她今年二十二岁，生日是哪天还没说。','An age does not identify the birthday date.'))],
text(u,'d','Two introductions, two stories','Read the facts without joining two people’s records.',[
('我今年二十二岁，过去在南方长大。','I am twenty-two this year and grew up in the south.'),('我二十三岁，在北方这个省长大。','I am twenty-three and grew up in this northern province.'),('你姐姐是商人，你也是吗？','Your elder sister is a businessperson; are you too?'),('不是，我还是学生。我们的故事要分开。','No, I am still a student; keep our stories separate.'),('今天星期三，见面时间变了吗？','Today is Wednesday; has the meeting time changed?'),('没变，三点在中心门口见。','It has not changed: meet at the centre entrance at three.'),('我得了三分，三分以上包括我吗？','I scored three; does at least three include me?'),('包括。但你姐姐的结果没说，不能替她选。','Yes. Your sister’s result has not been stated; you cannot choose for her.')],
[('mainidea','What mistake does the exchange prevent?',['Combining different people’s facts','Meeting at an unnamed time','Using a fictional province as a surname'],0),('detail','Who is a businessperson?',['The elder sister','Both students','The narrator'],0),('inference','Is the sister’s score known?',['No','Three','Twenty-three'],0)],drama=True),
text(u,'r','Introductions are not conclusions','Find age, meeting facts and boundaries of the evidence.',[
('今天星期三，我们三点在中心门口见。','Today is Wednesday; we meet at the centre entrance at three.'),('一位今年二十二岁，另一位二十三岁。','One person is twenty-two this year and the other twenty-three.'),('两个人在不同地方长大，不能说背景一样。','They grew up in different places; their backgrounds cannot be called identical.'),('姐姐是商人，弟弟是学生，身份也要分开。','The elder sister is a businessperson and the younger brother a student; keep their roles separate too.'),('她选了三张照片，有人说很像，有人说不一样。','She chose three photographs; some say they are alike and others say they differ.'),('过去的小组变成五个人，许多信息还没确认。','The earlier group became five people; much information is still unconfirmed.'),('有人在市里卖书，那本漂亮的书三十五块。','Someone sells books in the city; that attractive book costs thirty-five yuan.'),('一个人的结果不是所有人的结果，先看事实再得出结论。','One person’s result is not everyone’s; examine facts before drawing conclusions.')],
[('mainidea','What is the note asking the reader to do?',['Keep facts and people separate','Treat every score as identical','Invent birth dates from ages'],0),('detail','What price is stated?',['Thirty-five yuan','Twenty-two yuan','Three yuan'],0),('inference','Do the two ages reveal their birthdays?',['No','Yes, Wednesday','Yes, at three'],0)],[(0,'星期三'),(7,'结论')]),
text(u,'media','Two stories on one page','Read an original verse without filling in unstated background.',[
('今天星期三，门口三点见。','Today is Wednesday; meet at the entrance at three.'),('你从北方来，我从南方来。','You come from the north and I from the south.'),('过去不一样，现在坐一边。','Our pasts differ; now we sit beside each other.'),('一页写两人，不把故事连。','One page contains two people; do not merge their stories.'),('先听你说完，再把我的讲。','Hear your account out before telling mine.'),('朋友可以像，结果别乱猜。','Friends may resemble each other; do not guess their results.')],
[('inference','What does sitting together mean here?',['A shared present meeting, not identical histories','Identical birth dates','A proven shared score'],0)]),
dict(tf=[('以上','三分以上包括三分。','At least three includes three.','Three is included.',True,'The stated lower boundary is inclusive.'),('结果','姐姐的结果还没说。','The elder sister’s result has not been stated.','Her score is three.',False,'The result is unstated.')],reply=[('分开','姐姐是商人，你也是吗？','Your sister is a businessperson; are you too?',['不是，我还是学生。','所以我们都是星期三。','信用卡就是所有人。'],0,'State your own role.'),('变','三点见的时间变了吗？','Has the three o’clock meeting time changed?',['没变，还是三点。','许多就是二十二。','我们都是市长。'],0,'Answer the specific time question.')],fill=[('中心','三点在中心门口见。','Meet at the centre entrance at three.'),('过去','过去住这里，现在住别处。','Used to live here; now lives elsewhere.')],match=[('长',[('她在南方长大。','She grew up in the south.'),('她今年二十二岁。','She is twenty-two this year.'),('姐姐是商人。','The elder sister is a businessperson.')]),('结果',[('三分以上包括三分。','At least three includes three.'),('三分以下包括三分。','At most three includes three.'),('她的结果还没说。','Her result has not been stated.')])]),
[('Give your age','我今年二十二岁。','I am twenty-two this year.','Do not infer a birth date from this statement.'),('Correct a role assumption','姐姐是商人，我是学生。','My elder sister is a businessperson; I am a student.','Keep each person’s facts distinct.')],
[('你也是商人吗？','Are you a businessperson too?','Correct the assumption',['不是，我是学生。']),('今天星期几？','What day of the week is it today?','Use the scene’s stated day',['今天星期三。'])],
'Native check: nominal predicates in age/date/price contexts, inclusive 以上/以下 boundaries, 得 dé obtaining versus de complement particle, 长 zhǎng growing versus cháng long, 省 noun versus saving verb, and the original verse’s compressed wording. Scores are fictional scene facts, not app readiness claims.')

